def strategy(history, rng):
    n = len(history)
    if n < 10:
        return 'C'
    if n == 10:
        return 'D'
    if n == 11:
        return 'C'
    if n == 12:
        if history[10][1] == 'D':
            return 'C'
        else:
            return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]
    my_c = my_actions.count('C')
    my_d = n - my_c
    opp_d = opp_actions.count('D')
    last_my, last_opp = history[-1]

    if n >= 95:
        return 'D'

    if opp_d > n * 0.5:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            return 'D'
        else:
            return 'C'

    if opp_d == 0:
        if n > 60:
            if len(my_actions) >= 1 and my_actions[-1] == 'D':
                return 'C'
            if my_c - my_d >= 6:
                return 'D'
            return 'C'
        elif n > 40:
            if len(my_actions) >= 2 and 'D' in my_actions[-2:]:
                return 'C'
            if my_c - my_d >= 6:
                return 'D'
            return 'C'
        else:
            if len(my_actions) >= 3 and 'D' in my_actions[-3:]:
                return 'C'
            if my_c - my_d >= 6:
                return 'D'
            return 'C'
    else:
        if len(my_actions) >= 3 and 'D' in my_actions[-3:]:
            return 'C'
        if my_c - my_d >= 6:
            return 'D'
        return 'C'
